package dev.zomboid.autopsy;
import java.util.*;
public final class Minimal {
 static String label(String name){return switch(name){case "bleed"->"sangrado";case "fracture"->"fractura";case "bite"->"mordedura";case "gunshot","bullet"->"proyectil";case "cut"->"corte";case "infection"->"infección";case "dirty"->"contaminación";case "trauma"->"traumatismo";default->name;};}
 public static boolean render(Object g,Object font,int width,int height,long elapsed,Object report,Object detail){try{if(elapsed<850)return true;int rightWidth=Math.min(240,Math.max(140,width/2)),leftWidth=width-rightWidth;Autopsy.center(g,font,"HAS MUERTO",Math.max(width/2,leftWidth/2),20,0xFFC97870);int y=52;String cause=R.call(report,"cause").toString(),key=R.call(report,"causeKey").toString();if(!key.isEmpty()){Object translated=R.call(R.type("net.minecraft.network.chat.Component"),"translatable",key,R.call(report,"causeArgs"));cause=R.call(translated,"getString").toString();}y=Autopsy.text(g,font,"Causa de muerte: "+(cause.isEmpty()?"Sin registro":cause),14,y,Math.max(80,leftWidth-24),0xFFDCD6CA)+8;List<Object> parts=Autopsy.body(detail);boolean bleeding=false,bullet=false,critical=false;for(Object p:parts){Set<String> w=Autopsy.wounds(p);bleeding|=w.contains("bleed")&&Autopsy.health(p)<=.35;bullet|=w.contains("bullet")||w.contains("gunshot");critical|=Autopsy.health(p)<=.35;}y=Autopsy.text(g,font,Autopsy.mechanism(Autopsy.str(detail,"damage24"),key,bleeding,bullet,critical),14,y,Math.max(80,leftWidth-24),0xFFAE938B)+12;long ticks=((Number)R.call(report,"ticks")).longValue();String survived=ticks<0?"Sin registro":R.call(R.type("dev.survivorcreator.hearing.DeathReport"),"duration",ticks).toString();y=Autopsy.text(g,font,"Tiempo sobrevivido: "+survived,14,y,leftWidth-24,0xFFDCD6CA)+8;Autopsy.text(g,font,"Zombis abatidos: "+(int)Autopsy.num(detail,"zombies24"),14,y,leftWidth-24,0xFFA9BAA2);
 int top=55,bottom=height-47,figureHeight=Math.min(100,Math.max(65,bottom-top-30)),figureWidth=figureHeight*36/64,figureX=width-figureWidth-12,figureY=top;Object system=R.type("com.mojang.blaze3d.systems.RenderSystem"),texture=R.call(R.type("net.minecraft.resources.ResourceLocation"),"fromNamespaceAndPath","survivorcreator","textures/gui/autopsy_body.png");int[][] points={{18,6},{18,23},{29,27},{7,27},{22,47},{14,47},{24,61},{12,61}};List<String> notes=new ArrayList<>();for(Object p:parts){int index=Arrays.asList(Autopsy.PARTS).indexOf(Autopsy.str(p,"part"));if(index<0)continue;R.call(system,"setShaderColor",.74f,.76f,.72f,1f);try{R.call(g,"blit",texture,figureX,figureY,figureWidth,figureHeight,(float)((index%4)*256),(float)((index/4)*448),256,448,1024,896);}finally{R.call(system,"setShaderColor",1f,1f,1f,1f);}Set<String> wounds=Autopsy.wounds(p);if(wounds.isEmpty())continue;LinkedHashSet<String> names=new LinkedHashSet<>();for(String injury:wounds)names.add(label(injury));int count=names.size();String part=Autopsy.PART_NAMES.getOrDefault(Autopsy.str(p,"part"),Autopsy.str(p,"part"));notes.add(part+" · "+count+" lesión"+(count==1?"":"es")+"\n"+String.join(", ",names));int x=figureX+points[index][0]*figureWidth/36,py=figureY+points[index][1]*figureHeight/64;Autopsy.fill(g,x-2,py-1,5,3,0xFFB96A60);Autopsy.fill(g,x-1,py-2,3,5,0xFFB96A60);Autopsy.fill(g,figureX-7,py,Math.max(1,x-figureX+7),1,0x805B524C);}
 int notesX=leftWidth+7,notesWidth=Math.max(35,figureX-notesX-10),total=0;for(String note:notes)total+=((List<?>)R.call(font,"split",Autopsy.c(note.replace('\n',' ')),notesWidth)).size()*11+11;Object panel=R.type("dev.survivorcreator.hearing.DeathPanel");int max=Math.max(0,total-(bottom-top));R.set(panel,"maxScroll",max);int scroll=Math.max(0,Math.min(max,((Number)R.get(panel,"scroll")).intValue()));R.set(panel,"scroll",scroll);R.call(g,"enableScissor",notesX,top,figureX-6,bottom);try{int ny=top-scroll;for(String note:notes){String[] line=note.split("\n",2);ny=Autopsy.text(g,font,line[0],notesX,ny,notesWidth,0xFFC8B8AA);ny=Autopsy.text(g,font,line[1],notesX,ny+2,notesWidth,0xFFB96A60)+9;}if(notes.isEmpty())Autopsy.text(g,font,"Sin lesiones registradas",notesX,top,notesWidth,0xFF8D938B);}finally{R.call(g,"disableScissor");}Autopsy.center(g,font,"Clic izquierdo para continuar",width/2,height-20,0xFFA9BAA2);return true;}catch(Throwable e){R.warn("minimal death summary",e);return false;}}
}
